    val remainder = Output(UInt(width.W))
    val done     = Output(Bool())
  })

  // Simple non-restoring division
  val busy = RegInit(false.B)
  val cnt  = RegInit(0.U(log2Ceil(width+1).W))
  val quot = RegInit(0.U(width.W))
  val rem  = RegInit(0.U((width+1).W))
  val neg_quot = RegInit(false.B)
  val neg_rem  = RegInit(false.B)
  val divisor_reg = RegInit(0.U(width.W))

  io.done := !busy
  io.quotient  := Mux(neg_quot, (~quot + 1.U), quot)
  io.remainder := Mux(neg_rem,  (~rem(width-1, 0) + 1.U), rem(width-1, 0))

