    val abs_a = Mux(sgn_a, (~div + 1.U), div)
    val abs_b = Mux(sgn_b, (~divsr + 1.U), divsr)
    rem := Cat(0.U(1.W), abs_a)
    divisor_reg := abs_b
    quot := 0.U
    cnt := (width).U
    busy := true.B
  }.elsewhen(busy) {
    val next_rem = Cat(rem(width-1,0), quot(width-1)) - Cat(0.U(1.W), divisor_reg)
    when (next_rem(width)) {
      quot := Cat(quot(width-2, 0), 0.U(1.W))
      rem  := rem
